"""Build the draft validation report (Markdown).

Only the "Summary" section is free text (from the LLM or the demo template).
Every table is generated here directly from tool-result JSON, so the report's
numbers never pass through the LLM. The report ends with a blank engineering
sign-off block: the tool drafts, people decide.
"""

from __future__ import annotations

import json
from datetime import datetime

from .data_io import Dataset

DISCLAIMER = (
    "> **DRAFT - for engineering review.** Generated by PowerOps Agent, an independent student prototype "
    "(not an official product of any company). Acceptance criteria are illustrative values from a local plan "
    "file, not real product specifications. This report is read-only analysis: it makes no control actions and "
    "no release, safety or certification decisions."
)
GENERAL_LIMITATIONS = [
    "Acceptance criteria are illustrative; PASS/FAIL means 'compared with those values', not a qualification result.",
    "This tool does not decide whether a revision may be released, shipped or certified; that requires engineering sign-off.",
    "All measured values come from deterministic Python tools; the Summary text is a narrative of them.",
]
TITLES = {
    "run_validation_plan": "Validation scorecard",
    "compare_to_baseline": "Regression vs baseline",
    "check_power_balance": "Data integrity (power sensors)",
    "summarize_run": "Run summary",
    "detect_threshold_violations": "Threshold violations (illustrative limits)",
    "generate_plots": "Plots shown in the UI",
}
ORDER = list(TITLES)


def _fmt(x) -> str:
    if x is None:
        return "-"
    if isinstance(x, bool):
        return "yes" if x else "no"
    return str(x)


def _table(headers: list[str], rows: list[list]) -> list[str]:
    out = ["| " + " | ".join(headers) + " |", "|" + "|".join("---" for _ in headers) + "|"]
    return out + ["| " + " | ".join(_fmt(c) for c in row) + " |" for row in rows]


def _verdict(v: str) -> str:
    return {"PASS": "✓ PASS", "FAIL": "✕ FAIL"}.get(v, v)


def _section_for(name: str, r: dict) -> list[str]:
    if name == "run_validation_plan":
        s = r["summary"]
        lines = [f"Run: {r.get('run', '-')} · {s['pass']} PASS, {s['fail']} FAIL, {s['not_run']} NOT RUN, "
                 f"{s['inconclusive']} INCONCLUSIVE · plan: {r['plan_profile']}", ""]
        rows = [[x["test_id"], _verdict(x["verdict"]), x["kpi"], x["measured"], x["limit"], x["unit"]] for x in r["scorecard"]]
        lines += _table(["test", "verdict", "KPI", "measured", "illustrative limit", "unit"], rows)
        for t in r["tests"]:
            d = t["details"]
            if t["type"] == "efficiency" and d:
                continue  # one row per load point is enough; details are in the tool trace
            if t["type"] == "load_burst" and d.get("edges"):
                lines += ["", f"**{t['test_id']} edges** ({d['edge_count']} found; worst deviation at edge "
                              f"#{d['worst_deviation_edge']}, {d['worst_deviation_time_s']} s)", ""]
                lines += _table(["#", "time (s)", "dir", "delta (kW)", "baseline (V)", "peak dev (V)", "recovery (s)"],
                                [[e["edge_number"], e["time_s"], e["direction"], e["delta_kw"], e.get("baseline_v"),
                                  e.get("peak_deviation_v"), e.get("recovery_time_s") if e.get("recovered") else "not recovered"]
                                 for e in d["edges"]])
            if t["type"] == "grid_sag" and d:
                lines += ["", f"**{t['test_id']} event:** sag {d['sag_start_s']} to {d['sag_end_s']} s "
                              f"(min {d['min_grid_voltage_pu']} pu); grid deficit {d['deficit_kw']} kW; battery peak "
                              f"{d['peak_battery_kw']} kW; bus minimum at {d['min_bus_voltage_time_s']} s."]
            if t["type"] == "thermal" and d:
                lines += ["", f"**{t['test_id']} soak:** {d['start_temp_c']} °C at start, {d['end_temp_c']} °C at end "
                              f"({d['soak_duration_s']} s), peak at {d['peak_time_s']} s."]
        return lines

    if name == "compare_to_baseline":
        s = r["summary"]
        lines = [f"Candidate: {r['candidate_run']} · Baseline: {r['baseline_run']} · {s['regressions']} regression(s), "
                 f"{s['improvements']} improvement(s) across {s['kpis_compared']} KPIs · new failures: "
                 f"{', '.join(s['new_failures']) or 'none'}", ""]
        lines += _table(["test", "KPI", "baseline", "candidate", "delta", "tolerance", "change", "verdict"],
                        [[x["test_id"], x["kpi"], x["baseline"], x["candidate"], x["delta"], x["tolerance"],
                          ("**regression**" if x["change"] == "regression" else x["change"]),
                          f"{x['baseline_verdict']} → {x['candidate_verdict']}"] for x in r["kpi_deltas"]])
        return lines

    if name == "check_power_balance":
        b, p = r["battery_idle_check"], r["plausibility_check"]
        lines = [f"Verdict: **{r['verdict']}**", ""]
        lines += [f"- ⚠ {f}" for f in r["findings"]]
        lines += [f"- Battery-port idle check: median {b['median_battery_kw_healthy_grid']} kW with a healthy grid "
                  f"(tolerance ±{b['tolerance_kw']} kW) → {'pass' if b['pass'] else 'FAIL'}",
                  f"- Implied-efficiency plausibility: {p['windows_flagged']} of {p['windows_checked']} windows flagged "
                  f"({p['windows_skipped_low_power']} skipped at light load, {p['windows_skipped_grid_event']} near grid events)"]
        return lines

    if name == "summarize_run":
        run = r["run"]
        lines = [f"Samples: {run['n_samples']} · duration {run['duration_s']} s · ~{run['approx_sample_rate_hz']} Hz · "
                 f"largest gap {run['max_gap_s']} s · rack energy {_fmt(r['rack_energy_kwh'])} kWh", ""]
        lines += _table(["step", "plan tests", "start (s)", "end (s)", "samples", "mean rack (kW)"],
                        [[s["step"], "/".join(s["plan_tests"]) or "-", s["start_s"], s["end_s"], s["n_samples"],
                          s["mean_rack_power_kw"]] for s in r["test_steps"]])
        return lines

    if name == "detect_threshold_violations":
        rows = [[col, e["type"], f"{e['limit']} {c['unit']}", e["start_s"], e["end_s"], e["duration_s"], e["peak_value"],
                 e["peak_time_s"], e["test_step"]] for col, c in r["channels"].items() for e in c.get("events", [])]
        lines = [f"Total events: {r['total_events']}", ""] + [f"- `{col}`: {c['status']}" for col, c in r["channels"].items()]
        if rows:
            lines += [""] + _table(["channel", "type", "limit", "start (s)", "end (s)", "duration (s)", "peak", "peak at (s)",
                                    "step"], rows)
        return lines

    if name == "generate_plots":
        return [f"- `{p['plot_id']}`: {p['description']}" for p in r["plots_created"]] or [f"No plot: {r['status']}"]

    return ["```json", json.dumps(r, indent=2, default=str), "```"]


def build_report(result, dataset: Dataset, baseline: Dataset | None, plan: dict, generated_at: datetime) -> str:
    info = dataset.info()
    source = ("SYNTHETIC - generated by the PowerOps demo generator, not real measurements" if dataset.is_synthetic
              else "user-supplied file; provenance not verified by this tool")
    mode = result.mode + (f" (model: {result.model})" if result.model else "")
    lines = [
        "# SST Validation Report (DRAFT)", "", DISCLAIMER, "",
        "| | |", "|---|---|",
        f"| Run under test | {dataset.label} (`{info['name']}`, {info['n_samples']} samples, {info['duration_s']} s) |",
        f"| Baseline run | {baseline.label + ' (`' + baseline.name + '`)' if baseline else 'none loaded'} |",
        f"| Data source | {source} |",
        f"| Validation plan | {plan.get('profile_name')} (`{plan.get('_source_path', 'config')}`) |",
        f"| Agent mode | {mode} |",
        f"| Generated | {generated_at.strftime('%Y-%m-%d %H:%M:%S %Z').strip()} |",
        "", "## Question", "", result.question, "", "## Summary", "", result.answer or "_No summary text._", "",
    ]
    if result.notices:
        lines += ["### Notices", ""] + [f"- {n}" for n in result.notices] + [""]
    lines += ["## Number check", ""]
    if result.unverified_numbers:
        lines.append("⚠ These numbers in the Summary could not be matched to any tool output. Treat them with caution: "
                     + ", ".join(f"`{n}`" for n in result.unverified_numbers))
    else:
        lines.append("✓ Every number in the Summary matches a tool output, run metadata, the plan, or the question.")
    lines.append("")

    ok_records = sorted((r for r in result.tool_calls if r.ok), key=lambda r: ORDER.index(r.name) if r.name in ORDER else 99)
    if not ok_records:
        lines += ["_No analysis tools were run._", ""]
    for rec in ok_records:
        lines += [f"## {TITLES.get(rec.name, rec.name)}", ""] + _section_for(rec.name, rec.result) + [""]
    failed = [r for r in result.tool_calls if not r.ok]
    if failed:
        lines += ["### Tool errors", ""] + [f"- `{r.name}`: {r.result['error']}" for r in failed] + [""]

    lines += ["## Methods", ""]
    methods: dict[str, str] = {}
    for rec in ok_records:
        if rec.name == "run_validation_plan":
            for t in rec.result["tests"]:
                methods.setdefault(t["type"], t["method"])
        elif rec.result.get("method"):
            methods.setdefault(rec.name, rec.result["method"])
    lines += [f"- **{k}:** {v}" for k, v in methods.items()] or ["- No analysis methods were applied."]
    lines.append("")

    limitations: list[str] = []
    extra = [x for rec in ok_records for x in rec.result.get("limitations", [])]
    extra += [x for rec in ok_records if rec.name == "run_validation_plan" for t in rec.result["tests"] for x in t["limitations"]]
    for item in GENERAL_LIMITATIONS + extra:
        if item not in limitations:
            limitations.append(item)
    lines += ["## Limitations", ""] + [f"- {x}" for x in limitations] + [""]

    warnings = [("run under test", w) for w in dataset.warnings] + [("baseline", w) for w in (baseline.warnings if baseline else [])]
    if warnings:
        lines += ["## Data-quality warnings", ""] + [f"- ({who}) {w}" for who, w in warnings] + [""]

    lines += ["## Tool-call trace", ""]
    lines += _table(["#", "tool", "arguments", "status"],
                    [[i, f"`{r.name}`", f"`{json.dumps(r.arguments)}`", "ok" if r.ok else "error"]
                     for i, r in enumerate(result.tool_calls, start=1)]) if result.tool_calls else ["_No tools were called._"]
    lines += ["", "## Engineering review and sign-off", "",
              "_To be completed by a qualified engineer. PowerOps Agent prepares this draft and makes no decision._", "",
              "| Role | Name | Decision / comments | Date |", "|---|---|---|---|",
              "| Prepared by | PowerOps Agent (automated draft) | - | " + generated_at.strftime("%Y-%m-%d") + " |",
              "| Reviewed by | | | |", "| Approved by | | | |", ""]
    return "\n".join(lines)
